   "codice": "extends RefCounted


func run() -> float:
	var base_speed: float = 250.0
	var max_speed: float = 400.0
	var elapsed: float = 15.0
	var increment: float = 15.0
	var speed: float = minf(base_speed + elapsed * increment, max_speed)
	return speed
",
   "domanda": "Quanto vale `speed` alla fine?",
   "spiegazione": "`base_speed + elapsed * increment` fa `250.0 + 225.0 = 475.0`. La funzione `minf` sceglie il valore più piccolo tra 475.0 e `max_speed` (400.0), quindi restituisce 400.0."
  },
