   "codice": "extends RefCounted


func run() -> bool:
	var player_pos := Vector2(100.0, 100.0)
	var meteor_pos := Vector2(130.0, 140.0)
	var hit_distance: float = 50.0
	return player_pos.distance_to(meteor_pos) <= hit_distance
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "La distanza tra `(100, 100)` e `(130, 140)` si calcola con il teorema di Pitagora ($\sqrt{30^2 + 40^2}$), che dà esattamente `50.0`. Essendo minore o uguale a `hit_distance` (50.0), la condizione è vera."
  },
